{"results": [{"id": "FAM:SF-APPM-058", "label": "Study family SF-APPM-058: PNR shot-level season rates vs possession labels", "score": 1.494, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-058 (0.79)"], "attributes": {"observed_research_question": "PNR shot-level season rates vs possession labels", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "PBP-derived shot-level PNR rates sit in a realistic band (script notes possession-level rates will be higher) and vary by team as expected.", "observed_result": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No pass/fail gate in the output; rates are a calibration input for PBPProxyPNR (later logs show calibrated PNR ~17.9-19.6% of possessions).", "observed_sample_and_power": "30 teams, half_court_shots ~5994-6581", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-014"}]}, {"id": "FAM:SF-APPS-011", "label": "Study family SF-APPS-011: Regular season vs playoff PPP by play type (DRIVE over-prediction)", "score": 1.407, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-011 (0.80)"], "attributes": {"observed_research_question": "Regular season vs playoff PPP by play type (DRIVE over-prediction)", "auto_outcome_status": "supported", "observed_hypothesis": "DRIVE PPP is materially higher in RS than playoffs, so an RS-calibrated optimizer over-recommends DRIVE.", "observed_result": "DRIVE RS 1.198 vs PO 0.912 (-0.286, 25 teams); PNR -0.173; PULL_UP +0.301; others within -0.07.", "auto_failure_mechanism": "D_positive (no failure: positive result)", "observed_failure_evidence": "DRIVE playoff PPP 0.28